    bronze_degassinglance = { name = "Bronast plinilno kopje za livarstvo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast plinilno kopje za livarstvo za livarje." },
    silver_degassinglance = { name = "Srebrn plinilno kopje za livarstvo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn plinilno kopje za livarstvo za livarje." },
