DegassingLanceMaker.ironStock=18; DegassingLanceMaker.bronzeStock=14; DegassingLanceMaker.woodStock=10; DegassingLanceMaker.leatherStock=8; DegassingLanceMaker.silverStock=8; DegassingLanceMaker.goldStock=6; DegassingLanceMaker.jewelStock=4; DegassingLanceMaker.pearlStock=4
DegassingLanceMaker.productStock = {}; DegassingLanceMaker.buildings = {}; DegassingLanceMaker.maker = nil; DegassingLanceMaker.activeMaking = {}; DegassingLanceMaker.totalProducts = 0; DegassingLanceMaker.dayTimer = 0
function DegassingLanceMaker.init() DegassingLanceMaker.ironStock=18; DegassingLanceMaker.bronzeStock=14; DegassingLanceMaker.woodStock=10; DegassingLanceMaker.leatherStock=8; DegassingLanceMaker.silverStock=8; DegassingLanceMaker.goldStock=6; DegassingLanceMaker.jewelStock=4; DegassingLanceMaker.pearlStock=4; DegassingLanceMaker.productStock={}; DegassingLanceMaker.buildings={}; DegassingLanceMaker.maker=nil; DegassingLanceMaker.activeMaking={}; DegassingLanceMaker.totalProducts=0; DegassingLanceMaker.dayTimer=0; print("[DegassingLanceMaker] Royal Degassing Lance Maker System initialized (6 products, 4 buildings)") end
function DegassingLanceMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DegassingLanceMaker.maker={name=n or ("Plinilec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plinilec najet: %s (spretnost: %d)",DegassingLanceMaker.maker.name,s),"success") end; return true end
function DegassingLanceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DegassingLanceMaker.build(id) local ok,e=DegassingLanceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DegassingLanceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DegassingLanceMaker.getQualityBonus() local b=0; for _,bd in ipairs(DegassingLanceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DegassingLanceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and DegassingLanceMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and DegassingLanceMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and DegassingLanceMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and DegassingLanceMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and DegassingLanceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DegassingLanceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DegassingLanceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DegassingLanceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DegassingLanceMaker.buildings==0 then return false,"Potrebna plinilna delavnica" end; if not DegassingLanceMaker.maker then return false,"Potreben plinilec" end; return true end
function DegassingLanceMaker.make(pt,qty) qty=qty or 1; local ok,e=DegassingLanceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then DegassingLanceMaker.ironStock=DegassingLanceMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then DegassingLanceMaker.bronzeStock=DegassingLanceMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then DegassingLanceMaker.woodStock=DegassingLanceMaker.woodStock-d.woodCost*qty end; if d.leatherCost then DegassingLanceMaker.leatherStock=DegassingLanceMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then DegassingLanceMaker.silverStock=DegassingLanceMaker.silverStock-d.silverCost*qty end; if d.goldCost then DegassingLanceMaker.goldStock=DegassingLanceMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DegassingLanceMaker.jewelStock=DegassingLanceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DegassingLanceMaker.pearlStock=DegassingLanceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DegassingLanceMaker.maker then t=math.max(1,t-math.floor(DegassingLanceMaker.maker.skill/13)) end; table.insert(DegassingLanceMaker.activeMaking,{id="degassinglance_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DegassingLanceMaker.completeMaking(m) local q=1.0+(DegassingLanceMaker.getQualityBonus()/100); if DegassingLanceMaker.maker then q=q+(DegassingLanceMaker.maker.skill/140) end; q=math.min(2.5,q); DegassingLanceMaker.productStock[m.productType]=(DegassingLanceMaker.productStock[m.productType] or 0)+m.quantity; DegassingLanceMaker.totalProducts=DegassingLanceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DegassingLanceMaker.maker then DegassingLanceMaker.maker.itemsMade=DegassingLanceMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then DegassingLanceMaker.maker.skill=math.min(100,DegassingLanceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kopje izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"degassinglance.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function DegassingLanceMaker.update(dt) if not _G.state then return end; DegassingLanceMaker.dayTimer=DegassingLanceMaker.dayTimer+dt; if DegassingLanceMaker.dayTimer>=30 then DegassingLanceMaker.dayTimer=0; for i=#DegassingLanceMaker.activeMaking,1,-1 do local m=DegassingLanceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DegassingLanceMaker.completeMaking(m); table.remove(DegassingLanceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DegassingLanceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DegassingLanceMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DegassingLanceMaker.getStats() return {ironStock=DegassingLanceMaker.ironStock,bronzeStock=DegassingLanceMaker.bronzeStock,woodStock=DegassingLanceMaker.woodStock,leatherStock=DegassingLanceMaker.leatherStock,silverStock=DegassingLanceMaker.silverStock,goldStock=DegassingLanceMaker.goldStock,jewelStock=DegassingLanceMaker.jewelStock,pearlStock=DegassingLanceMaker.pearlStock,productStock=DegassingLanceMaker.productStock,numBuildings=#DegassingLanceMaker.buildings,hasMaker=DegassingLanceMaker.maker~=nil,makerName=DegassingLanceMaker.maker and DegassingLanceMaker.maker.name or "—",makerSkill=DegassingLanceMaker.maker and DegassingLanceMaker.maker.skill or 0,activeMaking=#DegassingLanceMaker.activeMaking,totalProducts=DegassingLanceMaker.totalProducts} end
return DegassingLanceMaker
